package ActionsCore_1ActionDefinition {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        action   def  Calculate  {
           doc  /* Reusable behavior */
           in  x  :  Real ;
           out  y  :  Real ;
        }
    }

    view ExposeExample {
        expose Main;
    }
}

